package org.eclipse.rdf4j.query.algebra.evaluation.impl.evaluationsteps;

import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.eclipse.rdf4j.model.util.Values.iri;

import java.util.Map;

import org.eclipse.rdf4j.query.QueryEvaluationException;
import org.eclipse.rdf4j.query.algebra.Service;
import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.algebra.Var;
import org.eclipse.rdf4j.query.impl.EmptyBindingSet;
import org.eclipse.rdf4j.query.impl.MapBindingSet;
import org.eclipse.rdf4j.repository.sparql.federation.SPARQLServiceResolver;
import org.junit.jupiter.api.Test;

class ServiceQueryEvaluationStepSecurityTest {

	@Test
	void rejectsConstantAndBoundPrivateServiceDuringEvaluation() {
		SPARQLServiceResolver resolver = new SPARQLServiceResolver();
		try {
			Service constant = service(Var.of("service", iri("http://127.0.0.1/constant")));
			assertThatThrownBy(() -> new ServiceQueryEvaluationStep(constant, constant.getServiceRef(), resolver)
					.evaluate(EmptyBindingSet.getInstance()))
							.isInstanceOf(QueryEvaluationException.class)
							.hasMessageContaining("Remote resource access denied");

			Service bound = service(Var.of("service"));
			MapBindingSet bindings = new MapBindingSet();
			bindings.addBinding("service", iri("http://127.0.0.1/bound"));
			assertThatThrownBy(() -> new ServiceQueryEvaluationStep(bound, bound.getServiceRef(), resolver)
					.evaluate(bindings))
							.isInstanceOf(QueryEvaluationException.class)
							.hasMessageContaining("Remote resource access denied");
		} finally {
			resolver.shutDown();
		}
	}

	private static Service service(Var serviceRef) {
		return new Service(serviceRef, new SingletonSet(), "SERVICE ?service { }", Map.of(), null, false);
	}
}
